.ci_baic_info{
  display: grid;
  grid-template-columns: 60px auto;
  grid-gap: 0px;
  margin-bottom: 15px;
  .ci_icon{
    align-self: center;
    justify-self: center;
    font-size: 25px; 
  }
}

.ci_config{
  width: 0px;
  height: 100%;
  position: absolute;
  top: 0px;
  left: 0px;
  transition: all 0.5s;
  background: #fff;
  overflow: hidden;
  z-index: 999;
}
